def as_choices(cls) -> Sequence[Tuple[int, str]]:
    return (
        (cls.ACTIVE, "active"),
        # TODO(epurkhiser): Remove once we're only using muted on the frontend
        (cls.MUTED, "disabled"),
        (cls.MUTED, "muted"),
        (cls.PENDING_DELETION, "pending_deletion"),
        (cls.DELETION_IN_PROGRESS, "deletion_in_progress"),
        (cls.WAITING, "waiting"),
    )
